function custom_login_logo() {
  echo '<style type=	ext/css">
    #login h1 a {
      background-image: url(' . get_stylesheet_directory_uri() . '/images/logo.png);
      width: 320px;
      height: 80px;
      background-size: contain;
      background-repeat: no-repeat;
    }
  </style>';
}
add_action('login_enqueue_scripts'

function disable_rest_api_for_guests($result) {
  if (!is_user_logged_in()) {
    return new WP_Error('rest_disabled', 'REST API disabled for guests', array('status' => 401));
  }
  return $result;
}
add_filter('rest_authentication_errors', 'disable_rest_api_for_guests');

@media only screen and (max-width: 768px) {
  .site-header {
    padding: 10px;
  }
  .main-navigation {
    display: none;
  }
  .mobile-menu-toggle {
    display: block;
  }
}
